from pathlib import Path
r=Path(__file__).resolve().parents[1];s=(r/'wacv2007-v6.tex').read_text()
s=s.replace('automatically tracked body landmarks','automatically estimated body landmarks')
s=s.replace('The masking sampler operates on seven overlapping regions:', 'A mask marks positions whose observations are withheld from the context network and whose features are predicted; the remaining positions provide context. The sampler operates on seven overlapping regions:')
